def build_lps(p: str) -> list[int]:
    m = len(p)
    lps = [0] * m
    length = 0
    i = 1
    while i < m:
        if p[i] == p[length]:
            length += 1
            lps[i] = length
            i += 1
        elif length > 0:
            length = lps[length - 1]
        else:
            lps[i] = 0
            i += 1
    return lps


def search(t: str, p: str) -> list[int]:
    n, m = len(t), len(p)
    lps = build_lps(p)
    result: list[int] = []
    i = j = 0
    while i < n:
        if t[i] == p[j]:
            i += 1
            j += 1
            if j == m:
                result.append(i - m)
                j = lps[j - 1]
        elif j > 0:
            j = lps[j - 1]
        else:
            i += 1
    return result


